    def show_help_message(self):
        msg = QtWidgets.QMessageBox()
        msg.setWindowTitle("帮助")
        msg.setText("请在输入框中输入当前/欲抵达层级的层级编号，仅数字，例如level11输入11\n随后点击开始导航")
